(() => {
  const q = window.__wa = {
    origin: location.origin, realFetch: window.fetch.bind(window), permits: [], gates: new Map(),
    owned: new Set(), runs: new Set(), ids: {}, accepted: [], events: [], readonlyPosts: [],
    violations: [], jsErrors: [], failures: [], shown: [], finishes: [], opens: new Map(),
    actions: new Map(), pendingPress: null, progressWrites: [],
  };
  q.assert = (condition, message) => { if (!condition) throw Error(message); };
  q.until = async (predicate, milliseconds = 45000) => {
    const end = Date.now() + milliseconds;
    while (Date.now() < end) {
      if (predicate()) return true;
      await new Promise(resolve => setTimeout(resolve, 40));
    }
    return false;
  };
  q.read = async path => {
    const url = new URL(path, location.href);
    q.assert(url.origin === q.origin, 'read left the owned origin');
    const response = await q.realFetch(url.href);
    q.assert(response.ok, 'owned read refused: ' + url.pathname + ' ' + response.status);
    return response.json();
  };
  q.safe = () => location.origin === q.origin && q.violations.length === 0
    && q.jsErrors.length === 0 && q.failures.length === 0 && q.permits.length === 0;
  q.allow = (path, { tag, mode = 'pass', body = null, detail = '' } = {}) => {
    const url = new URL(path, location.href);
    const owned = /^\/api\/jobs\/([^/]+)\/(cancel|pause)$/.exec(url.pathname);
    q.assert(url.origin === q.origin && (url.pathname === '/api/generate'
      || (owned && q.owned.has(owned[1]))), 'permit targets an unowned mutation: ' + path);
    q.assert(typeof tag === 'string' && !q.gates.has(tag), 'permit tag missing or reused');
    q.assert(['pass', 'hold-pass', 'http500', 'hold-http500'].includes(mode), 'unknown response mode');
    const grant = { path: url.pathname + url.search, tag, mode, detail,
      body: body === null ? null : JSON.stringify(body), seen: false,
      responseReady: false, released: !mode.startsWith('hold-') };
    if (!grant.released) grant.wait = new Promise(resolve => { grant.release = resolve; });
    q.gates.set(tag, grant);
    q.permits.push(grant);
    return grant;
  };
  q.release = tag => {
    const grant = q.gates.get(tag);
    q.assert(grant && grant.seen && grant.responseReady && !grant.released, 'no pending owned response: ' + tag);
    grant.released = true;
    grant.release();
  };
  q.done = async tag => {
    q.assert(await q.until(() => {
      const action = q.actions.get(tag);
      q.assert(action && !action.error, 'watched handler failed: ' + tag + ' ' + (action?.error || ''));
      return action.done;
    }), 'watched handler did not settle: ' + tag);
  };
  q.releaseDone = async tag => { q.release(tag); await q.done(tag); };
  q.view = () => JSON.stringify({ job: currentJob, busy, progress: els.progressText.textContent,
    mirror: els.jobMirror.textContent, cancel: els.cancel.textContent,
    cancelHeld: els.cancel.getAttribute('aria-disabled'), pause: els.pause.textContent,
    pauseHeld: els.pause.getAttribute('aria-disabled'), error: els.error.textContent });
  window.addEventListener('error', event => q.jsErrors.push(String(event.message || 'window error')));
  window.addEventListener('unhandledrejection', event => q.jsErrors.push(String(event.reason)));
  const realShowError = showError;
  showError = (...args) => { q.shown.push(String(args[0] ?? '')); return realShowError(...args); };
  const realProgress = setProgressText;
  setProgressText = (...args) => {
    q.progressWrites.push({ id: currentJob, spoken: args[0] });
    return realProgress(...args);
  };
  const realFinish = finishJob;
  finishJob = (id, data, options) => {
    q.finishes.push({ id, status: data.status, count: data.image_count,
      submitted: !!options?.submitted, foreign: !!options?.foreign });
    return realFinish(id, data, options);
  };
  // Observe the original async onclick return without replacing product helpers.
  for (const kind of ['cancel', 'pause']) {
    const original = els[kind].onclick;
    q.assert(typeof original === 'function', 'watched button has no original handler: ' + kind);
    els[kind].onclick = function(event) {
      const tag = q.pendingPress;
      q.pendingPress = null;
      const action = q.actions.get(tag);
      q.assert(action && action.kind === kind && action.id === currentJob, 'unexpected watched button press');
      const promise = original.call(this, event);
      q.assert(promise && typeof promise.then === 'function', 'original watched handler did not return its Promise');
      void promise.then(() => { action.done = true; }, error => {
        action.error = String(error); q.failures.push(action.error); action.done = true;
      });
      return promise;
    };
  }
  const RealEventSource = window.EventSource;
  window.EventSource = class extends RealEventSource {
    constructor(url, options) {
      const address = new URL(url, location.href);
      const match = /^\/api\/jobs\/([^/]+)\/stream$/.exec(address.pathname);
      if (address.origin !== q.origin || !match || !q.owned.has(match[1])) {
        q.violations.push('unowned event stream: ' + address.pathname);
        throw Error('event stream is not an owned fake job');
      }
      q.opens.set(match[1], (q.opens.get(match[1]) || 0) + 1);
      super(url, options);
    }
  };
  window.fetch = async (input, options) => {
    const address = new URL(typeof input === 'string' || input instanceof URL ? input : input.url, location.href);
    const method = String(options?.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase();
    const path = address.pathname + address.search;
    if (address.origin !== q.origin) {
      q.violations.push('off-origin ' + method + ' ' + address.origin);
      throw Error('fixture refused an off-origin request');
    }
    if (method === 'GET' || method === 'HEAD') return q.realFetch(input, options);
    const finish = /^\/api\/runs\/([^/]+)\/finish\/preview$/.exec(address.pathname);
    if (method === 'POST' && !address.search && (
      ['/api/grid/preview', '/api/prompt/analyze'].includes(address.pathname)
      || (finish && q.runs.has(decodeURIComponent(finish[1])))
    )) {
      q.readonlyPosts.push(address.pathname);
      return q.realFetch(input, options);
    }
    const body = options?.body ?? null;
    const at = q.permits.findIndex(grant => grant.path === path
      && grant.body === (body === null || body === undefined || body === '' ? null : String(body)));
    if (method !== 'POST' || at < 0) {
      q.violations.push(method + ' ' + path);
      throw Error('fixture refused an unapproved mutation: ' + method + ' ' + path);
    }
    const grant = q.permits.splice(at, 1)[0];
    grant.seen = true;
    const event = { path, tag: grant.tag, mode: grant.mode, forwarded: false };
    q.events.push(event);
    const mode = grant.mode.replace(/^hold-/, '');
    let response;
    if (mode === 'pass') {
      event.forwarded = true;
      response = await q.realFetch(input, options);
      if (address.pathname === '/api/generate' && response.ok) {
        const accepted = await response.clone().json();
        q.assert(typeof accepted.job_id === 'string' && /^[a-f0-9]{12}$/.test(accepted.job_id), 'no real fake job receipt');
        q.assert(!q.owned.has(accepted.job_id) && !(accepted.more?.length), 'duplicate or split fake submission');
        q.assert(typeof grant.submitLabel === 'string' && grant.tag === 'submit-' + grant.submitLabel,
          'accepted submission has no exact fixture label');
        q.owned.add(accepted.job_id);
        q.accepted.push(accepted.job_id);
        grant.acceptedId = accepted.job_id;
        q.ids[grant.submitLabel] = accepted.job_id;
        if (typeof accepted.run_id === 'string') q.runs.add(accepted.run_id);
      }
    } else {
      response = new Response(JSON.stringify({ detail: grant.detail }),
        { status: 500, headers: { 'Content-Type': 'application/json' } });
    }
    grant.responseStatus = response.status;
    grant.responseReady = true;
    if (!grant.released) await grant.wait;
    return response;
  };
  q.submit = async (label, seed) => {
    const payload = { prompt: 'watched action smoke ' + label, width: 256, height: 256, steps: 12, runs: 2, seed };
    const grant = q.allow('/api/generate', { tag: 'submit-' + label, body: payload });
    grant.submitLabel = label;
    const shownAt = q.shown.length, failuresAt = q.failures.length;
    let refused = '', completed = false;
    void startJob('/api/generate', payload, {
      onRefused: error => { refused = String(error?.message ?? error); },
    }).catch(error => { refused = String(error); q.failures.push(refused); })
      .finally(() => { completed = true; });
    const diagnostic = () => JSON.stringify({ label, seen: grant.seen,
      status: grant.responseStatus ?? null, accepted: grant.acceptedId ?? null,
      submitting, retained: !!grant.acceptedId && submissions.has(grant.acceptedId),
      modelState, serverOffline, busy, refused,
      shown: q.shown.slice(shownAt).filter(Boolean).slice(-2) });
    q.assert(await q.until(() => {
      const error = refused || q.failures.slice(failuresAt).join('; ');
      q.assert(!error, 'submission refused: ' + diagnostic());
      q.assert(!(grant.responseReady && grant.responseStatus >= 400), 'submission HTTP refusal: ' + diagnostic());
      if (grant.acceptedId && !submitting && submissions.has(grant.acceptedId)) return true;
      q.assert(!(completed || (!grant.acceptedId && q.shown.slice(shownAt).some(Boolean))),
        'submission did not retain an accepted receipt: ' + diagnostic());
      return false;
    }), 'submission acceptance timed out: ' + diagnostic());
    q.assert(q.owned.has(q.ids[label]) && submissions.has(q.ids[label]), 'accepted receipt missing: ' + label);
    return q.ids[label];
  };
  q.press = async (kind, id, tag, { mode = 'pass', detail = '' } = {}) => {
    q.assert(['pause', 'cancel'].includes(kind) && q.owned.has(id) && currentJob === id && busy,
      'button would target another watched job');
    const button = els[kind];
    q.assert(!button.disabled && button.getAttribute('aria-disabled') === 'false', 'watched button is held: ' + kind);
    const value = kind === 'pause' ? button.textContent === 'Pause' : null;
    const path = '/api/jobs/' + id + '/' + kind + (kind === 'pause' ? '?value=' + value : '');
    q.allow(path, { tag, mode, detail });
    q.assert(!q.pendingPress && !q.actions.has(tag), 'another physical press is being dispatched');
    q.actions.set(tag, { id, kind, done: false });
    q.pendingPress = tag;
    button.focus({ preventScroll: true });
    button.click();
    q.assert(q.pendingPress === null, 'physical press did not reach its original handler');
    q.assert(await q.until(() => {
      const grant = q.gates.get(tag), action = q.actions.get(tag);
      q.assert(!action.error && !(action.done && !grant.seen), 'physical press sent no approved request: ' + tag);
      return grant.responseReady;
    }), 'physical request did not answer: ' + tag);
    if (!mode.startsWith('hold-')) await q.done(tag);
  };
  q.queuedPauseSetup = async id => {
    q.assert(q.owned.has(id) && id !== currentJob && queuedIds.includes(id), 'queue-pause setup does not own a queued job');
    const before = await q.read('/api/jobs/' + id);
    q.assert(before.status === 'queued' && before.image_count === 0, 'queue-pause setup missed its pre-start boundary');
    const path = '/api/jobs/' + id + '/pause?value=true';
    q.allow(path, { tag: 'setup-pause-C' });
    const after = await api(path, { method: 'POST' });
    q.assert(after.job_id === id && after.pause_requested === true && after.image_count === 0,
      'owned queued pause did not acknowledge');
  };
  q.watchedPaused = async id => {
    q.assert(await q.until(() => busy && currentJob === id && skipSnapshot?.paused
      && els.pause.textContent === 'Resume' && q.opens.get(id) === 1), 'real successor did not become watched and paused');
    const job = await q.read('/api/jobs/' + id);
    q.assert(job.paused === true && !['done', 'error', 'cancelled'].includes(job.status), 'watched pause is not real');
  };
  return true;
})()
